<?php
namespace Tests\Feature;
use App\Models\Employee; use App\Models\PerformanceCycle; use App\Models\Tenant; use App\Services\PerformanceReviewService; use Illuminate\Support\Str; use RuntimeException; use Tests\TestCase;
class PerformanceReviewServiceTest extends TestCase { public function test_review_cycle_submit_acknowledge_and_close_rules():void{if(config('database.default')!=='mysql')$this->markTestSkipped('Requires MySQL.');$tenant=Tenant::create(['name'=>'Perf '.Str::random(5)]);try{tenancy()->initialize($tenant);$employee=Employee::create(['name'=>'Perf Employee','national_id'=>'PERF-1','hire_date'=>'2026-01-01','salary'=>'500.000','status'=>'active']);$cycle=PerformanceCycle::create(['name'=>'H2','starts_on'=>'2026-07-01','ends_on'=>'2026-12-31','status'=>'draft']);$service=app(PerformanceReviewService::class);$service->open($cycle);$this->assertSame(1,$service->generate($cycle));$review=$cycle->reviews()->first();try{$service->close($cycle);$this->fail('Draft review should block closing.');}catch(RuntimeException){$this->assertSame('open',$cycle->fresh()->status);} $review=$service->submit($review,['overall_rating'=>'4.5','goals_rating'=>'4','competency_rating'=>'4.25','strengths'=>'Reliable','improvements'=>'Delegation','goals'=>'Lead project'],null);$this->assertSame('submitted',$review->status);$review=$service->acknowledge($review,$employee,'Seen');$this->assertSame('acknowledged',$review->status);$this->assertSame('closed',$service->close($cycle)->status);}finally{if(tenancy()->initialized)tenancy()->end();$tenant->delete();}} }
